function solve({config,state,event}){
  let s=state;
  if(s===null){
    s={g:config.groups.map(x=>({id:x.id,required:x.required,open:null})),p:config.panels.map(x=>({id:x.id,group:x.group,enabled:x.enabled}))};
    for(let i=0;i<s.g.length;i++) if(s.g[i].required) for(const p of s.p) if(p.group===s.g[i].id&&p.enabled){s.g[i].open=p.id;break}
  }
  const gs=s.g,ps=s.p,gi={},pi={};
  gs.forEach((g,i)=>gi[g.id]=i);ps.forEach((p,i)=>pi[p.id]=i);
  const e=event;
  if(e.type==='toggle'&&pi[e.id]!==undefined){
    const p=ps[pi[e.id]],k=gi[p.group];
    if(p.enabled){if(gs[k].open===p.id){if(!gs[k].required)gs[k].open=null}else gs[k].open=p.id}
  }else if(e.type==='enabled'&&pi[e.id]!==undefined) ps[pi[e.id]].enabled=e.value;
  else if(e.type==='close'&&gi[e.group]!==undefined){let k=gi[e.group];if(!gs[k].required)gs[k].open=null}
  else if(e.type==='mode'&&gi[e.group]!==undefined) gs[gi[e.group]].required=e.required;
  for(const g of gs){if(g.open!==null&&!ps[pi[g.open]].enabled)g.open=null;if(g.open===null&&g.required)for(const p of ps)if(p.group===g.id&&p.enabled){g.open=p.id;break}}
  const open={},expanded=[],unsatisfied=[];
  for(const g of gs)open[g.id]=g.open;
  for(const p of ps)if(open[p.group]===p.id)expanded.push(p.id);
  for(const g of gs)if(g.required&&g.open===null)unsatisfied.push(g.id);
  unsatisfied.sort();
  return {state:s,output:{open,expanded,unsatisfied}};
}
